// Generated by ssg 1.0.1 (ssg build --target cloudflare). Edit freely: ssg does not
// overwrite this file unless you pass --force.
//
// Serves the HTML, Markdown or plain-text variant of each page, chosen by the Accept header:
// text/html wins, then text/markdown, and anything else gets text.
const LINK = true;
const FORMAT = true;
const PAGE_CACHE = "public, max-age=300";

const TYPES = {
  html: "text/html; charset=utf-8",
  md: "text/markdown; charset=utf-8",
  txt: "text/plain; charset=utf-8"
};

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const path = url.pathname;

    const accept = request.headers.get("Accept") ?? "";

    let extension = "txt";

    if (accept.includes("text/html")) {
      extension = "html";
    } else if (accept.includes("text/markdown")) {
      extension = "md";
    }

    const fetchAsset = (pathname) => {
      const assetUrl = new URL(request.url);
      assetUrl.pathname = pathname;
      return env.ASSETS.fetch(new Request(assetUrl, request));
    };

    const notFound = async () =>
      respond(await fetchAsset(`/404/index.${extension}`), 404, extension, "");

    // ssg's marker file is not content.
    if (path === "/.ssg-dist") return notFound();

    // Real files (style.css, keys/gpg, foo/index.html, ...) are served as-is.
    if (!path.endsWith("/")) {
      const exact = await env.ASSETS.fetch(request);

      if (exact.status !== 404)
        return exact;
    }

    if (path === "/404" || path === "/404/") {
      // The 404 page itself is still a 404.
      return notFound();
    }

    let response;

    if (path.endsWith("/")) {
      // ssg publishes foo.md and foo/index.md as foo/index.{html,md,txt}.
      response = await fetchAsset(`${path}index.${extension}`);
    } else {
      // foo.md stays foo.{html,md,txt} when foo/index.md also exists.
      response = await fetchAsset(`${path}.${extension}`);

      if (response.status === 404) {
        // /foo is a directory page: redirect to /foo/ so its relative links resolve.
        const index = await fetchAsset(`${path}/index.${extension}`);

        if (index.status !== 404) {
          url.pathname = `${path}/`;
          return Response.redirect(url.toString(), 301);
        }
      }
    }

    if (response.status === 404) {
      // Anything missing gets 404.md, in whichever format was asked for.
      return notFound();
    }

    return respond(response, response.status, extension, path);
  }
};

// `path` is the page's URL when it ends in "/", for the Link header; "" for none.
function respond(response, status, extension, path) {
  const headers = new Headers(response.headers);
  headers.set("Vary", "Accept");
  headers.set("Content-Type", TYPES[extension]);

  if (FORMAT)
    headers.set("X-SSG-Format", extension);

  if (status === 200 && PAGE_CACHE)
    headers.set("Cache-Control", PAGE_CACHE);

  if (LINK && extension === "html" && status === 200 && path.endsWith("/"))
    headers.set("Link", `<${path}index.md>; rel="alternate"; type="text/markdown"`);

  return new Response(response.body, {
    status,
    statusText: status === response.status ? response.statusText : "Not Found",
    headers
  });
}
